/* Il dizionario italiano — la lingua sorgente del progetto.
 *
 * È un file di dati, come i `dati-*.js`: si carica come `<script>` prima di
 * `i18n.js`, che lo assorbe in memoria all'avvio. Da lì in poi ogni `t(chiave)`
 * è una lettura da `Map`, e il cambio lingua non costa nessuna richiesta e
 * nessun conto.
 *
 * Perché non `it.json`: questa applicazione si apre anche con un doppio clic su
 * `index.html`, e da `file://` una `fetch('it.json')` è vietata dal browser —
 * la lingua non arriverebbe. Il contenuto è comunque un oggetto piatto
 * chiave→testo, cioè JSON con una riga di intestazione.
 *
 * Questo è il dizionario di **ripiego**: quando una chiave manca nella lingua
 * scelta, il gestore torna qui. Una chiave che manca *anche* qui è un difetto,
 * e si vede — sullo schermo compare il nome della chiave.
 *
 * Tre cose da sapere prima di aggiungerne una:
 *   - i segnaposto sono `{nome}`; `{n}` è il numero e si scrive col separatore
 *     della lingua (mille virgola cinque qui, mille punto cinque in inglese);
 *   - una voce che dipende da una quantità si scrive `{ uno: …, altri: … }`, e
 *     a scegliere è `Intl.PluralRules`, non noi;
 *   - le chiavi `ui.*` nascono dallo slug della frase italiana: sono generate,
 *     e chi ne aggiunge una a mano faccia lo stesso, così restano leggibili in
 *     `index.html`.
 */

