    'tel.deriva.asseTroppoBasso': 'Asse polare troppo basso di {primi}′.',
    'tel.deriva.azioneAbbassa': 'Abbassa la scala della latitudine di {primi}′ ({gradi}°).',
    'tel.deriva.azioneAlza': 'Alza la scala della latitudine di {primi}′ ({gradi}°).',
    'tel.frazione.0': 'Ferma: non si è mossa',
    'tel.frazione.1': 'Un filo (un ventesimo di campo)',
    'tel.frazione.2': 'Un decimo di campo',
    'tel.frazione.3': 'Un ottavo di campo',
    'tel.frazione.4': 'Un quarto di campo',
    'tel.frazione.5': 'Un terzo di campo',
    'tel.frazione.6': 'Mezzo campo',
    'tel.frazione.7': 'Uscita dal campo',
    'tel.deriva.serveSolo': 'Serve solo se fai foto a lunga posa o se lavori sopra i 150×. Per guardare, i 6 passi qui sopra bastano: salta pure questa parte.',
    'tel.deriva.comeFunziona': 'È il metodo più preciso che esista senza elettronica, e non richiede nessun accessorio: si centra una stella, si aspetta 4–5 minuti senza toccare niente, e si guarda da che parte è scivolata. Direzione e velocità dello scivolamento dicono <em>esattamente</em> di quanto è storto l\'asse. Poi l\'app traduce il conto in due frasi: quanto girare le viti di azimut e quanto alzare o abbassare la scala della latitudine.',
    'tel.deriva.stelleAzimut': 'Stelle buone <strong>per l\'errore in azimut</strong> (a Sud, vicino al meridiano):',
    'tel.deriva.stelleAltezza': 'Stelle buone <strong>per l\'errore in altezza</strong> (basse a Est o a Ovest):',
    'tel.deriva.nessunaAdatta': 'Nessuna adatta in questo momento.',
    'tel.deriva.centraLaStella': 'Centra <strong class="text-white">{stella}</strong> nell\'oculare più spinto{ingrandimento}, poi avvia il cronometro e non toccare più niente. Bastano 4–5 minuti.',
    'tel.deriva.avviaCronometro': 'Avvia il cronometro',
    'tel.deriva.fermoHoMisurato': 'Fermo: ho misurato',
    'tel.deriva.annulla': 'Annulla',
    'tel.deriva.dopoMinuti': 'Dopo {minuti} minuti su {stella}:',
    'tel.deriva.doveIlNord': 'Per sapere da che parte è il Nord nel campo: muovi la manopola della declinazione verso i valori crescenti e guarda da che parte scappa la stella. Quella è il Nord.',
    'tel.deriva.andataNord': 'È andata verso NORD',
    'tel.deriva.andataSud': 'È andata verso SUD',
    'tel.deriva.diQuanto': 'Di quanto? Il campo dell\'oculare è {campo} a {x}×.',
    'tel.deriva.registraMisura': 'Registra la misura',
    'tel.deriva.rigaMisura': '{minuti} min · {verso} {secondi}″',
    'tel.deriva.versoNord': 'verso Nord',
    'tel.deriva.versoSud': 'verso Sud',
    'tel.deriva.togli': 'togli',
    'tel.deriva.troppoBreve': 'Misure troppo brevi per dire qualcosa. La deriva da errore di allineamento vale qualche secondo d\'arco al minuto: sotto i {minimo} minuti quello che si vede muovere è l\'aria, non l\'asse polare. Rifai la misura lasciando passare almeno 4–5 minuti.',
    'tel.deriva.insufficiente': 'Le due misure vengono da stelle troppo simili fra loro: dicono la stessa cosa due volte. Aggiungine una presa in una zona di cielo diversa (una a Sud vicino al meridiano, una bassa a Est o a Ovest).',
    'tel.deriva.correzioniDaFare': 'Correzioni da fare',
    'tel.deriva.misuraSola': 'Misura sola: l\'errore in {asse} resta sconosciuto. Aggiungi una misura su una stella dell\'altro gruppo per avere tutt\'e due.',
    'tel.deriva.autonomia': 'Con questo errore residuo ({primi}′), a {x}× un oggetto centrato ti resta nel campo per circa <strong class="text-white">{minuti} minuti</strong>{motore}.',
    'tel.deriva.colMotore': ' con il motore acceso',
    'tel.deriva.azzeraMisure': 'Azzera tutte le misure',

