    // Le due cifre per le manopole
    'tel.manopole.arTitolo': 'Ascensione retta — cerchio orario',
    'tel.manopole.decTitolo': 'Declinazione — cerchio verticale',
    'tel.manopole.decimali': '{valore} decimali',
    'tel.manopole.coordinateDiStanotte': 'Coordinate di stanotte',
    'tel.manopole.precessione': ' (precessione applicata: sul catalogo, in J2000, sono AR {ar} e Dec {dec})',
    'tel.manopole.siSpostano': ' — pianeti e Luna si spostano di ora in ora',
    'tel.manopole.tempoSiderale': 'Tempo siderale locale adesso:',
    'tel.manopole.angoloOrarioBersaglio': 'angolo orario del bersaglio',
    'tel.manopole.comeSiUsano': 'Come si usano sulla Spica (e su qualunque EQ3)',
    'tel.manopole.decAssolutaTitolo': 'La declinazione è assoluta.',
    'tel.manopole.decAssoluta': 'Il cerchio verticale, una volta tarato, vale tutta la vita: allenta la manopola, muovi finché l\'indice segna <span class="font-mono text-white">{valore}</span>, ristringi. Se non ti torna, taralo una volta sola: centra una stella di cui conosci la declinazione e ruota il cerchio finché legge il suo valore.',
    'tel.manopole.arNoTitolo': 'L\'ascensione retta no.',
    'tel.manopole.arNo': 'Il cerchio orario gira insieme al cielo, quindi va ritarato a ogni sessione (e, senza motore, ogni volta che passa mezz\'ora): si centra una stella nota e si fa scorrere il cerchio — è apposta che è morbido — finché legge l\'ascensione retta di quella stella. Da quel momento i numeri sono buoni. Il passo qui sotto lo fa fare all\'app.',
    'tel.manopole.precisione': 'Precisione realistica di questi cerchi: mezzo grado o poco meno. Ti porta dentro il campo del cercatore, non al centro dell\'oculare — l\'ultimo pezzetto lo fai a occhio.',
    'tel.tabella.intro': 'Ascensione retta e declinazione di tutto quello che è sopra l\'orizzonte adesso, nel formato dei cerchi graduati. Sono coordinate di stanotte, già portate avanti dal J2000 del catalogo.',
    'tel.tabella.oggetto': 'Oggetto',
    'tel.tabella.ar': 'AR',
    'tel.tabella.dec': 'Dec',
    'tel.tabella.alt': 'Alt',

    // I cerchi graduati
    'tel.cerchi.passo1Titolo': 'Passo 1 di 2: tara il cerchio orario.',
    'tel.cerchi.passo1': 'Centra nell\'oculare una di queste stelle — sono le più luminose alte in cielo adesso — poi premi il suo nome. L\'app ti dirà su che numero far scorrere il cerchio.',
    'tel.cerchi.nessunaStella': 'Nessuna stella luminosa abbastanza alta in questo momento.',
    'tel.cerchi.nonRiconosci': 'Non riconosci nessuna di queste stelle? Va bene anche il bersaglio di un giro precedente, o la Luna: l\'importante è sapere con certezza su cosa sei puntato.',
    'tel.cerchi.seiPuntato': 'Sei puntato su <strong class="text-white">{nome}</strong>{eta}: fai scorrere il cerchio orario finché l\'indice legge <strong class="font-mono text-blue-300">{ar}</strong>, e il cerchio verticale <strong class="font-mono text-amber-300">{dec}</strong>. Tarato.',
    'tel.cerchi.daMinuti': { uno: '(da {n} min)', altri: '(da {n} min)' },
    'tel.cerchi.minuti': { uno: '{n} min', altri: '{n} min' },
    'tel.cerchi.passo2Titolo': 'Passo 2 di 2: muovi le due manopole.',
    'tel.cerchi.manopolaAr': 'Manopola di ascensione retta',
    'tel.cerchi.manopolaDec': 'Manopola di declinazione',
    'tel.cerchi.verso': 'verso {verso}',
    'tel.cerchi.fincheOrario': 'finché il cerchio orario legge',
    'tel.cerchi.fincheVerticale': 'finché il cerchio verticale legge',
    'tel.cerchi.conMotore': 'Motore acceso: lo scarto in ascensione retta è fisso, non cambia mentre armeggi.',
    'tel.cerchi.senzaMotore': 'Senza motore il cielo scorre: la lettura in ascensione retta qui sopra tiene già conto del tempo passato dalla taratura{eta}, ma premi <em>Ricalcola</em> appena prima di muovere la manopola.',
    'tel.cerchi.arrivatoInFondo': 'Arrivato in fondo, guarda nell\'oculare più largo: l\'oggetto è lì dentro o poco fuori. Se non c\'è, muovi piano in declinazione di mezzo grado avanti e indietro — l\'errore dei cerchi è quasi sempre lì.',
    'tel.cerchi.ricalcola': 'Ricalcola adesso',
    'tel.cerchi.ripartiDaQui': 'Sono arrivato: riparti da qui',
    'tel.cerchi.cambiaStella': 'Cambia stella di taratura',

    // I salti di stella
    'tel.salti.nessunaPartenza': 'Nessuna stella luminosa abbastanza vicina: conviene arrivarci con i cerchi graduati o con il telefono sul tubo.',
    'tel.salti.nonDisponibile': 'Percorso non disponibile.',
    'tel.salti.intro': 'Con un cercatore a punto rosso non si «cerca»: si salta da una stella che si vede a occhio nudo alla successiva, un campo alla volta. Parti da {stella} ({costellazione}, magnitudine {mag}).',
    'tel.salti.rigaSalto': ' — {gradi} verso {direzione}, da {da}',
