    // Il push-to col telefono sul tubo
    'tel.tubo.leDueManopole': 'le due manopole',
    'tel.tubo.ilTuboConLeMani': 'il tubo con le mani',
    'tel.tubo.intro': 'È il puntamento assistito, fatto con quello che hai già: fissa il telefono al tubo con l\'adattatore che sta nella scatola, centra una stella nota e premi <em>Sono su questa stella</em>. Da quel momento il telefono sa dove guarda il tubo, e mentre muovi {spinta} ti dice quanto manca al bersaglio — con un pallino che si avvicina al centro e un battito che si infittisce.',
    'tel.tubo.solidale': 'Il telefono va <strong class="text-slate-200">solidale al tubo</strong>: se scivola, l\'allineamento è da rifare.',
    'tel.tubo.lontanoDalFerro': 'Lontano da calamite e dal contrappeso: il ferro sposta la bussola.',
    'tel.tubo.nienteCavi': 'Non serve nessun cavo e nessuna montatura motorizzata.',
    'tel.tubo.accendi': 'Accendi il push-to',
    'tel.tubo.attivoSensori': 'Attivo i sensori…',
    'tel.tubo.sensoriNonDisponibili': 'Sensori non disponibili',
    'tel.tubo.senzaPermesso': 'Senza il permesso ai sensori di movimento il push-to non può funzionare. Su iPhone si concede da Impostazioni → Safari → Movimento e orientamento; restano i cerchi graduati e i salti di stella.',
    'tel.tubo.sonoSu': 'Sono su {stella}',
    'tel.tubo.dallaPrima': '{gradi}° dalla prima',
    'tel.tubo.nessunaAdatta': 'Nessuna stella adatta abbastanza alta e abbastanza lontana da quelle già usate.',
    'tel.tubo.passo1Titolo': 'Passo 1: dimmi dove sei puntato adesso.',
    'tel.tubo.passo1': 'Centra una di queste stelle nell\'oculare — meglio in quello più largo, e poi rifinisci — e premi il suo nome. Non serve che sia precisa al secondo d\'arco: serve che sia quella giusta.',
    'tel.tubo.spegniPushTo': 'Spegni il push-to',
    'tel.tubo.secondaStellaTitolo': 'Aggiungi una seconda stella: è il passo che raddoppia la precisione.',
    'tel.tubo.secondaStella': 'Con una stella sola l\'app deve credere alla bussola del telefono, che sbaglia di qualche grado. Con due stelle <strong class="text-slate-200">lontane fra loro</strong> l\'errore della bussola viene calcolato e tolto: si passa da «dentro il cercatore» a «dentro l\'oculare». Centra un\'altra stella e premi il suo nome.',
    'tel.tubo.altraStella': 'Aggiungi un\'altra stella (migliora ancora)',
    'tel.tubo.sincronizzaTitolo': 'Da usare quando hai il bersaglio centrato: sincronizza qui e il prossimo salto parte preciso',
    'tel.tubo.sincronizza': 'Ce l\'ho centrato: sincronizza qui',
    'tel.tubo.ripartiDaZero': 'Riparti da zero',
    'tel.tubo.spegni': 'Spegni',
    'tel.tubo.vibrazioneAccesa': 'Vibrazione accesa',
    'tel.tubo.vibrazioneSpenta': 'Vibrazione spenta',
    'tel.tubo.bipAcceso': 'Bip acceso',
    'tel.tubo.bipSpento': 'Bip spento',
    'tel.tubo.battitoNota': 'Servono per puntare senza guardare lo schermo: il battito si infittisce mentre ti avvicini.',
    'tel.qualita.unPunto': 'Allineato su {stelle}, un punto solo: la precisione è quella della bussola del telefono, quindi qualche grado. Ti porta dentro il campo del cercatore.',
    'tel.qualita.baseCorta': '{punti} punti ({stelle}), ma tutti nella stessa zona di cielo ({base}° fra i più lontani): l\'errore della bussola non si può ricavare. Aggiungi una stella in una parte di cielo diversa — meglio ancora, dall\'altra parte del meridiano.',
    'tel.qualita.buona': '{punti} punti ({stelle}), base di {base}°. Errore della bussola calcolato e tolto: <strong class="text-white">{theta}°</strong>. I punti sono coerenti entro <strong class="text-white">{scarto}°</strong>, ed è più o meno la precisione che puoi aspettarti.',
    'tel.qualita.seETanto': 'Se è tanto, o il supporto del telefono si è mosso, o una delle stelle non era quella che credevi: prova a ripartire da zero.',

