    // Il pannello Serata
    'tel.serata.primaDiCominciare': 'Prima di cominciare',
    'tel.serata.portaFuoriTitolo': 'Porta fuori il telescopio.',
    'tel.serata.portaFuori': 'Uno specchio da {mm} mm ci mette circa {minuti} minuti a mettersi alla temperatura dell\'aria. Finché è più caldo, dentro al tubo si muovono correnti d\'aria che fanno tremolare l\'immagine esattamente come farebbe il cattivo seeing: si crede di avere un telescopio scarso, e invece è solo tiepido.',
    'tel.serata.tramontoTitolo': 'Tramonto.',
    'tel.serata.tramonto': 'È il momento di allineare la montatura al polo: si fa meglio con ancora un po\' di luce, e la Polare compare presto.',
    'tel.serata.buioTitolo': 'Buio astronomico.',
    'tel.serata.buio': 'Da qui in poi il cielo non migliora più: è tutto quello che il tuo posto può dare.',
    'tel.serata.schiarisce': 'Comincia a schiarire.',
    'tel.serata.rugiadaTitolo': 'Rugiada:',
    'tel.serata.rugiadaAlta': 'rischio alto{quando}.',
    'tel.serata.daCircaLe': ', da circa le {ora}',
    'tel.serata.rugiadaMedia': 'possibile a fine notte.',
    'tel.serata.rugiadaBassa': 'improbabile stanotte.',
    'tel.serata.rugiadaScarto': 'Temperatura e punto di rugiada si avvicinano fino a {scarto} di scarto.',
    'tel.serata.rugiadaConsiglio': 'Su un Newton si appanna il secondario, che sta in cima al tubo e guarda il cielo. Un paraluce di gommapiuma attorno alla bocca del tubo rimanda l\'appannamento di un paio d\'ore, e costa due euro.',
    'tel.serata.fuoriPortata': 'fuori portata',
    'tel.serata.piuGrandeDelCampo': 'più grande del campo',
    'tel.serata.vicinoAllaLuna': 'troppo vicino alla Luna ({gradi}°)',
    'tel.serata.cieloSchiarito': 'cielo schiarito dalla Luna',
    'tel.serata.scalettaTitolo': 'La scaletta di stanotte',
    'tel.serata.scalettaIntro': 'In ordine di quando ogni oggetto è più alto{luna}. Tocca un nome per portarlo nel pannello Punta.',
    'tel.serata.lunaIlluminata': ' · Luna illuminata al {perc}%',
    'tel.serata.nienteDiInteressante': 'Niente di interessante abbastanza alto stanotte.',
    'tel.serata.regoleTitolo': 'Le regole della serata',
    'tel.serata.regola1Titolo': 'Venti minuti di buio, veri.',
    'tel.serata.regola1': 'L\'occhio si adatta lentamente e si «resetta» con un lampo di luce bianca. Schermo dell\'app in modalità notte, torcia rossa, niente telefono.',
    'tel.serata.regola2Titolo': 'Comincia dal più basso a Ovest.',
    'tel.serata.regola2': 'Sta tramontando: se lo lasci per ultimo, non c\'è più.',
    'tel.serata.regola3Titolo': 'Guarda di lato.',
    'tel.serata.regola3': 'Sulle macchie deboli la visione distolta (guardare a fianco dell\'oggetto, non dritto) fa vedere il 30% in più: la parte sensibile della retina non sta al centro.',
    'tel.serata.regola4Titolo': 'Aspetta.',
    'tel.serata.regola4': 'Cinque minuti sullo stesso oggetto mostrano tre volte quello che si vede in dieci secondi. L\'atmosfera si ferma a tratti, e in quegli attimi c\'è tutto.',

    // Il pannello Cura
    'tel.cura.collimazione': 'Collimazione',
    'tel.cura.newton': 'Newton',
    'tel.cura.telescopio': 'telescopio',
    'tel.cura.introNewton': 'Un {strumento} a f/{f} è veloce, e i telescopi veloci sono severi: mezzo millimetro di specchio storto e le stelle diventano cometine. È il motivo per cui tanti telescopi economici vengono giudicati scarsi quando invece sono solo scollimati — e si sistema in dieci minuti, gratis.',
    'tel.cura.primaDiToccare': 'Prima di toccare le viti: fallo di giorno, con il telescopio orizzontale, e gira sempre poco per volta (un ottavo di giro). Se ti perdi, il primario è quasi sempre quello giusto da correggere per ultimo.',
    'tel.cura.nonNewton': 'Il tuo strumento non è un Newton: la collimazione, se serve, si fa in modo diverso e molto più di rado. Il test stellare qui sotto vale lo stesso.',
    'tel.collimazione.guarda.titolo': 'Guarda dentro il focheggiatore',
    'tel.collimazione.guarda.testo': 'Di giorno, senza oculare, togli il tappo e guarda nel tubo del focheggiatore tenendo l\'occhio centrato. Devi vedere: lo specchio secondario (l\'ovale), il primario riflesso dentro di lui, e i tre ganci del primario.',
    'tel.collimazione.guarda.controllo': 'Il secondario appare tondo e centrato nel tubo del focheggiatore?',
    'tel.collimazione.centraSecondario.titolo': 'Centra il secondario sotto il focheggiatore',
    'tel.collimazione.centraSecondario.testo': 'Se l\'ovale è spostato, agisci sulla vite centrale del ragno (quella che allunga o accorcia il sostegno) e sulla rotazione del secondario. Non toccare ancora le tre viti piccole: quelle servono al passo dopo.',
    'tel.collimazione.centraSecondario.controllo': 'L\'ovale è al centro e mostra tutto il primario?',
    'tel.collimazione.inclinaSecondario.titolo': 'Inclina il secondario per vedere tutto il primario',
    'tel.collimazione.inclinaSecondario.testo': 'Con le tre viti piccole del secondario, inclinalo finché il riflesso del primario è centrato nell\'ovale e si vedono tutti e tre i ganci, uguali.',
    'tel.collimazione.inclinaSecondario.controllo': 'I tre ganci del primario si vedono tutti, alla stessa distanza dal bordo?',
    'tel.collimazione.regolaPrimario.titolo': 'Regola il primario',
    'tel.collimazione.regolaPrimario.testo': 'Dietro al tubo ci sono tre viti di regolazione (spesso con tre di bloccaggio). Allenta i bloccaggi, poi ruota le viti di regolazione poco per volta finché il puntino centrale del primario finisce al centro di tutto. Un ottavo di giro alla volta.',
    'tel.collimazione.regolaPrimario.controllo': 'Il puntino centrale è al centro del riflesso?',
    'tel.collimazione.verificaStella.titolo': 'Verifica sulla stella',
    'tel.collimazione.verificaStella.testo': 'Di notte punta una stella luminosa a 100× o più, e sfocala di poco. Devi vedere un disco di anelli concentrici, con il buco centrale (l\'ombra del secondario) esattamente in mezzo. Se il buco è spostato da una parte, la collimazione è ancora fuori da quella parte.',
    'tel.collimazione.verificaStella.controllo': 'Gli anelli sono concentrici?',
    'tel.cura.testStellare': 'Il test stellare',
    'tel.cura.testIntro': 'La verifica che conta si fa sul cielo: punta una stella luminosa a {x}× e sfocala di poco. Confronta con queste tre figure.',
    'tel.cura.testNota': 'Se gli anelli ballano e non stanno fermi mai, non è collimazione: è seeing (aria instabile) oppure lo specchio non è ancora arrivato in temperatura. Aspetta mezz\'ora e riprova.',
    'tel.test.ok': 'Collimazione buona',
    'tel.test.ok.testo': 'Anelli concentrici, buco centrale in mezzo. Va bene così: non toccare più niente.',
    'tel.test.poco': 'Leggermente scollimato',
    'tel.test.poco.testo': 'Il buco è spostato di poco. Si vede solo sfocando: a fuoco l\'immagine è ancora buona. Correggibile con un ottavo di giro.',
    'tel.test.molto': 'Scollimato',
    'tel.test.molto.testo': 'Il buco è chiaramente da una parte. A fuoco le stelle hanno una codina: qui il telescopio rende molto meno di quello che potrebbe.',
    'tel.cura.altreCose': 'Le altre cose che rovinano una serata',
    'tel.cura.specchioCaldoTitolo': 'Specchio caldo.',
    'tel.cura.specchioCaldo': '{minuti} minuti fuori prima di iniziare.',
    'tel.cura.treppiedeTitolo': 'Treppiede sull\'erba.',
    'tel.cura.treppiede': 'Su terreno morbido ogni tocco fa ballare l\'immagine per cinque secondi. Meglio il cemento, o affondare bene le punte.',
    'tel.cura.ingrandimentoAltoTitolo': 'Ingrandimento troppo alto.',
    'tel.cura.ingrandimentoAlto': 'Sopra i {x}× l\'immagine peggiora e basta. Nelle notti mediocri anche 100× sono troppi.',
    'tel.cura.pulitoTitolo': 'Specchio pulito troppo spesso.',
    'tel.cura.pulito': 'Un velo di polvere toglie meno contrasto di un graffio. Si lava ogni qualche anno, non ogni stagione.',
    'tel.cura.telefonoTitolo': 'Guardare dopo aver guardato il telefono.',
    'tel.cura.telefono': 'Bastano due secondi di schermo bianco per buttare via venti minuti di adattamento al buio.',

