    'did.retro.nota': 'Il cappio a destra è disegnato in coordinate eclittiche vere: la sua forma cambia a ogni passaggio perché dipende da quanto l\'orbita del pianeta è inclinata sulla nostra. I due dischi sono fuori scala — a scala vera la Terra sarebbe invisibile.',
