    'did.retro.spiegaRetro': 'Adesso {nome} <strong>sta andando all\'indietro</strong> fra le stelle. Guarda a sinistra: la Terra è dalla stessa parte del Sole rispetto a {nome} e lo sta sorpassando, come un\'auto sulla corsia interna. Il filo che li unisce ruota all\'indietro, e il pianeta con lui.',
    'did.retro.spiegaDiretto': 'Adesso {nome} <strong>va avanti</strong>, verso oriente, come fa quasi sempre. Il sorpasso deve ancora cominciare (o è già finito): la Terra e {nome} si stanno avvicinando lungo le rispettive orbite.',
