    'did.kep.ponteTredTitolo': 'Apre il Sistema Solare in 3D, dove le orbite sono quelle vere',
    'did.kep.ponteLezione': 'E perché stanno tutte sullo stesso piano?',
    'did.kep.ponteLezioneTitolo': 'Apre la lezione dell\'eclittica',
    'did.kep.targhettaForma': 'Prima legge — l\'orbita è un\'ellisse, il Sole sta in un fuoco',
    'did.kep.targhettaAree': 'Seconda legge — in tempi uguali si spazzano aree uguali',
    'did.kep.targhettaArmonia': 'Terza legge — il quadrato dell\'anno è il cubo della distanza',
    'did.kep.uaDalSole': '{n} UA dal Sole',
    'did.kep.ilSuoAnno': 'il suo anno: {anno}',
    'did.kep.spiegaArmonia': 'Un pianeta a <strong>{ua} UA</strong> impiegherebbe <strong>{anno}</strong> a fare un giro: è {ua} elevato a 1,5. Il doppio della distanza non fa il doppio dell\'anno, ne fa quasi il triplo — ed è questa sproporzione che rende il viaggio verso i pianeti esterni così lento, e le loro finestre di lancio così frequenti (perché li raggiungiamo quasi subito, tanto loro non scappano).',
    'did.kep.uaConSemiasse': '{n} UA (a = 1 UA)',
    'did.kep.semprelaStessa': '{n} UA² — sempre la stessa',
    'did.kep.meseDodici': 'mese {n}/12',
    'did.kep.spiegaCerchio': 'Con l\'eccentricità quasi a zero l\'ellisse è indistinguibile da un cerchio: è il caso della Terra (e = {ecc}), ed è il motivo per cui per duemila anni nessuno si è accorto che non era un cerchio. <strong>Alza lo schiacciamento</strong> e guarda dove va a finire il Sole: non al centro, ma in uno dei due fuochi — l\'altro resta vuoto.',
    'did.kep.spiegaFuoco': 'Il Sole sta in <strong>uno dei due fuochi</strong>, mai al centro. La distanza dal Sole oscilla fra {min} e {max} UA nello stesso giro, e con lei oscilla tutto: la velocità, la luce ricevuta, la durata delle stagioni.',
    'did.kep.spiegaAree': 'I dodici spicchi hanno forme diversissime — stretti e lunghi vicino all\'afelio, larghi e corti al perielio — ma <strong>la stessa area</strong>, e il pianeta ne percorre uno per ogni dodicesimo del suo anno. Detto al contrario: vicino al Sole deve correre ({perielio} km/s al perielio) e lontano può andare piano ({afelio} km/s all\'afelio). È la conservazione del momento angolare, scoperta prima che avesse un nome.',

