    'did.aurL.nasoScudo': 'Naso dello scudo',
    'did.aurL.indiceKp': 'Indice Kp',
    'did.aurL.daCasaTua': 'Da casa tua',
    'did.aurL.notaGesto': 'Gira la scena col dito (o trascinando col mouse) per guardarla da un\'altra parte. Per avvicinarti: la rotella del mouse, due dita sullo schermo, o il + tenuto premuto. Il ⟲ rimette tutto a posto, e il ⛶ prende tutto lo schermo.',
