    'did.aurL.ilRossoCorto': 'il rosso',
    'did.aurL.quattroNotti': 'Quattro notti in cui è successo davvero',
    'did.aurL.quattroNottiNota': 'Da quasi tutta Europa l\'aurora capita una volta ogni molti anni: aspettare che succeda per vederla non è un piano. Queste righe portano il planetario in un altro posto e in un\'altra notte — quelle vere — con l\'ovale acceso al Kp di allora. La posizione dell\'app non si tocca: è una visita, e dal pannello <em>Tempo e luogo</em> del planetario si torna a casa con un tasto.',
    'did.aurL.ponteCielo': 'L\'aurora nel cielo di casa',
    'did.aurL.ponteCieloTitolo': 'Apre il planetario da qui, con l\'ovale acceso alla tempesta scelta qui sopra',
    'did.aurL.ponteTred': 'Il Sistema Solare adesso',
    'did.aurL.ponteTredTitolo': 'Apre la vista dall\'esterno all\'istante di adesso',
