    'did.aurL.raggiEMila': '{raggi} R⊕ · {mila} mila km',
    'did.aurL.posizioneIgnota': 'posizione ignota',
    'did.aurL.nienteSottoOrizzonte': 'niente: resta sotto l\'orizzonte',
    'did.aurL.archiVerdi': 'archi verdi, fino a {gradi}°',
    'did.aurL.soloBagliore': 'solo bagliore rosso, fino a {gradi}°',
    'did.aurL.moduloNonCaricato': 'Il modulo delle aurore non è caricato.',
    'did.aurL.tSottoOrizzonte': 'Da <strong>{luogo}</strong>, con Kp {kp}, l\'ovale resta {km} km più in là e la curvatura della Terra lo nasconde tutto: non si affaccia nemmeno la cima. Alza il Kp e guarda da che punto comincia a spuntare — quel numero, per il tuo parallelo, dice tutto.',
    'did.aurL.tCasoItaliano': '<strong>Ecco il caso italiano.</strong> Da {luogo} l\'ovale è a {km} km: il verde a 120 km di quota sta a {verde}°, cioè {dove}, mentre il rosso a 250 km si affaccia a {rosso}° e la cima della tenda arriva a {cima}°. Aspettati un bagliore rosato, non archi verdi. Nessuno l\'ha deciso: è la Terra che è tonda.',
    'did.aurL.oltreIlBordo': 'sotto l\'orizzonte, oltre il bordo della Terra',
    'did.aurL.talmenteBasso': 'talmente basso da essere spento dall\'aria',
    'did.aurL.tAddosso': 'Da <strong>{luogo}</strong> con Kp {kp} l\'ovale è praticamente addosso — {km} km — e le tende arrivano a {cima}° sopra l\'orizzonte, cioè quasi allo zenit. Da sotto l\'ovale l\'aurora non si guarda «verso {verso}»: si guarda in su, e la corona aurorale si apre a raggiera sopra la testa.',
    'did.aurL.tArchi': 'Da <strong>{luogo}</strong> con Kp {kp} l\'ovale è a {km} km: abbastanza vicino perché il verde stia sopra l\'orizzonte ({verde}°) e si vedano gli archi, non solo il bagliore. La cima della tenda arriva a {cima}° verso {verso}.',
    'did.aurL.daLiSottoOrizzonte': 'Da lì, quella notte: l\'ovale resta sotto l\'orizzonte.',
    'did.aurL.aGradi': '{nome} a <strong>{gradi}°</strong>',
    'did.aurL.sottoOrizzonte': '{nome} sotto l\'orizzonte',
    'did.aurL.daLiQuellaNotte': 'Da lì, quella notte: {verde}, {rosso}, la cima della tenda a <strong>{cima}°</strong> verso {verso}.',
    'did.aurL.vero': 'vero',
    'did.aurL.portamiLi': 'Portami lì nel planetario',
    'did.aurL.daQui': 'Da qui',
    'did.aurL.avvisoTesta': '{luogo}, {data}, Kp {kp}:',
    'did.aurL.avvisoVerdi': 'l\'ovale {nome} è a {km} km e gli archi verdi arrivano a {cima}° verso {verso}.',
    'did.aurL.avvisoRosso': 'l\'ovale {nome} è a {km} km — il verde resta sotto la curvatura, si affaccia il rosso fino a {cima}° verso {verso}.',
    'did.aurL.avvisoNiente': 'con questo Kp, da qui l\'ovale resta sotto l\'orizzonte: alza la slitta del Kp nella scheda Cielo.',
