    'did.tram.giornoCorto': 'Di giorno: noi azzurri, Marte color paglia.',
    'did.tram.giornoLungo': 'Di giorno: da noi il blu sparpagliato in tutto il cielo, su Marte la polvere che se lo mangia e lascia il colore della sabbia.',
    'did.tram.tramontoCorto': 'Al tramonto si scambiano: noi rossi, Marte azzurro.',
    'did.tram.tramontoLungo': 'Al tramonto si scambiano: il nostro cielo diventa rosso, e su Marte il blu si stringe attorno al Sole invece di sparpagliarsi.',
    'did.tram.otticoCorto': 'Molecole: Terra 0,097, Marte 0,006. Polvere: 0,5.',
    'did.tram.otticoLungo': 'Spessore ottico a 550 nm — molecole: Terra 0,097, Marte 0,006 (sedici volte meno). Polvere di Marte: 0,5, cioè ottanta volte la sua aria.',
    'did.tram.trascinaCorto': 'Trascina su e giù per muovere il Sole.',
    'did.tram.trascinaLungo': 'Trascina su e giù per muovere il Sole — si muove in tutt\'e due i cieli.',
