    'did.tram.col.profondo': 'arancione profondo',
    'did.tram.letturaBarra': '{ora} · Sole a {gradi}°',
    'did.tram.dalParallelo': 'Stai guardando dal parallelo <strong>{lat}° {emiLat}</strong>. Oggi il Sole è a picco sul parallelo <strong>{decl}° {emiDecl}</strong>,',
    'did.tram.nonSorge': 'e da qui non sorge affatto: gira tutto il giorno sotto l\'orizzonte.',
    'did.tram.nonSaleSopra': 'quindi da qui non sale mai sopra <strong>{gradi}°</strong>. L\'ora è quella solare vera: mezzogiorno è quando il Sole passa in meridiano.',
    'did.tram.spiegaCrepuscolo': 'Il disco è scomparso sotto l\'orizzonte ottico. Quello che resta in cielo è <strong>crepuscolo</strong>: luce che non arriva più dritta, ma diffusa dall\'aria alta che da lassù vede ancora il Sole. È lo stesso anello arancione che, sul globo, si vede di taglio dallo spazio.',
    'did.tram.spiegaRifrazione': 'Geometricamente il Sole è già <strong>{gradi}° sotto l\'orizzonte</strong>: senza atmosfera sarebbe tramontato. Lo vediamo ancora perché l\'aria piega il raggio di <strong>{primi}′</strong> — più del mezzo grado che il disco stesso misura, e per questo il tramonto «vero» e quello che si guarda non sono lo stesso istante.',
    'did.tram.spiegaAria': 'La luce attraversa <strong>{km} km</strong> d\'aria invece degli 8,4 che basterebbero col Sole dritto sopra la testa: <strong>{x} volte</strong> tanto. La diffusione di Rayleigh cresce come λ⁻⁴, quindi il blu se ne va per primo — ne resta il <strong>{blu}%</strong> — mentre del rosso arriva ancora il <strong>{rosso}%</strong>. Il blu perso non è sparito: è il colore del cielo attorno.',
    'did.tram.targaGlobo': '<strong>Trascina la Terra</strong> per farla girare. Il Sole sta fermo.',
    'did.tram.guardaIlGlobo': 'Guarda il globo:',
    'did.tram.notaGesto': 'Un dito di traverso fa girare la Terra — cioè fa passare le ore — e in su o in giù alza e abbassa il punto di vista; due dita avvicinano.',
    'did.tram.targaAria': '<strong>Trascina il Sole</strong> — scala vera, curvatura compresa. Il trattino verticale è il cammino più corto possibile: <em>quello lungo ci sta dentro tante volte quanta è la massa d\'aria</em>.',
    'did.tram.targaCielo': '<strong>Trascina il Sole su e giù.</strong> Il disco è alla misura vera, schiacciato dalla rifrazione, e accanto c\'è dove sarebbe senza aria',
    'did.tram.targaBande': 'Quanta luce resta, colore per colore',
    'did.tram.targaMarte': 'Stessa ora, stessa scala: a cambiare è solo <em>chi</em> diffonde la luce.',
    'did.tram.notaMarte': 'Da noi diffondono le molecole d\'aria, mille volte più piccole della lunghezza d\'onda: è il regime di <strong>Rayleigh</strong>, dove la diffusione cresce come λ⁻⁴ e va un po\' in tutte le direzioni. Il blu viene sparpagliato per tutto il cielo — e da qualunque parte si guardi, ne arriva: <strong>cielo azzurro</strong>. Su Marte l\'aria è lo 0,6% della nostra e di Rayleigh non resta niente: a diffondere è la <strong>polvere</strong>, granelli di un paio di micron, cioè grandi <em>come</em> la lunghezza d\'onda. Una polvere così non guarda il colore quando ferma la luce, ma la ridiffonde con un picco in avanti tanto più stretto quanto più corta è l\'onda — e per giunta è ossido di ferro, che il blu se lo mangia. Lontano dal Sole vince l\'assorbimento (<strong>cielo color paglia</strong>), vicino al Sole vince il picco in avanti (<strong>alone azzurro al tramonto</strong>). È il nostro cielo esattamente al contrario.',
    'did.tram.etichettaSlitta': 'Quanto è girata la Terra dal mezzogiorno',
    'did.tram.portamiA': 'Portami a:',
    'did.tram.daDoveGuardi': 'Da dove guardi:',
    'did.tram.letturaOra': 'Ora solare del posto',
    'did.tram.letturaVero': 'Dov\'è il Sole per davvero',
    'did.tram.letturaRifrazione': 'Quanto lo alza l\'aria',
    'did.tram.letturaApparente': 'Dove lo vediamo',
    'did.tram.letturaMassa': 'Aria attraversata',
    'did.tram.letturaLuce': 'Luce che arriva',
    'did.tram.letturaColore': 'Colore che ne esce',
    'did.tram.letturaAdesso': 'Il Sole adesso, da casa tua',
    'did.tram.ponteCielo': 'Vedi il tramonto di stasera',
    'did.tram.ponteCieloT': 'Porta il planetario all\'ora vera del tramonto, da casa tua',
    'did.tram.ponteTred': 'Guarda la Terra da fuori',
