    'terreno.nessunaQuota': 'nessuna quota è arrivata',
    'terreno.restaQuelloCheHo': 'intanto resta l\'orizzonte che ho già, un po\' meno fine.',
    'terreno.restaDisegnato': 'intanto resta l\'orizzonte disegnato.',
    'terreno.nonRiuscito': 'Non sono riuscito a prendere la forma del terreno: {che}. Riprovo da solo fra poco; {resta}',
    'terreno.affino': 'L\'orizzonte qui sopra è già quello vero: lo sto affinando{q}{dove}…',
    'terreno.stoMisurandoIlTerreno': 'Sto misurando com\'è fatto il terreno attorno a te{q}{dove}…',
    'terreno.serveRete': 'Apri il planetario da un posto con la rete e prendo la forma vera del terreno qui attorno.',
    'terreno.seiA': 'Sei a {m} m.',
    'terreno.direzioniStimate': '({n} direzioni su {tot} sono stimate: la rete non le ha portate tutte, e le chiedo ancora ogni tanto finché non arrivano)',
    'terreno.paesaggio.mare': 'il mare',
    'terreno.paesaggio.pianura': 'pianura',
    'terreno.paesaggio.collina': 'colline',
    'terreno.paesaggio.montagna': 'montagne',
    'terreno.quasiTuttIntorno': 'quasi tutt\'intorno',
    'terreno.perMetaOrizzonte': 'per metà orizzonte',
    'terreno.verso': 'verso {direzione}',
    'terreno.unTrattoVerso': 'un tratto verso {direzione}',
    'terreno.attornoATe': 'Attorno a te: {pezzi}.',
    'terreno.orizzonteLibero': 'L\'orizzonte è libero in tutte le direzioni: non c\'è niente che copra.',
    'terreno.laMontagna': 'la montagna',
    'terreno.laCollina': 'la collina',
    'terreno.puntoPiuAlto': 'Il punto più alto è a {gradi}° verso {direzione}{cosa}.',
    'terreno.altroveLibero': 'Da qualche parte l\'orizzonte è invece completamente libero.',
    'terreno.piuBasso': 'Il più basso è a {gradi}°.',
    'terreno.osmNonHaRisposto': 'OpenStreetMap non ha risposto',
    'terreno.osmFuoriTempo': 'OpenStreetMap non ha risposto in tempo',
    'terreno.osmIrraggiungibile': 'non riesco a raggiungere OpenStreetMap',
    'terreno.cittaSpente': 'Luci delle città spente: orizzonte nero, come da un deserto.',
    'terreno.cittaCerco': 'Sto cercando i paesi qui attorno…',
    'terreno.cittaSupplenza': 'Per ora però ci sono solo le città grandi: OpenStreetMap non ha risposto, si riprova da sé fra qualche minuto.',
    'terreno.cittaTrovate': 'Sull\'orizzonte ci sono le luci di {n} centri abitati: il chiarore più forte è quello di {nome}, a {km} km verso {dove}. È la direzione in cui conviene NON cercare le cose deboli.',
    'terreno.cimeSpente': 'Nomi delle montagne spenti.',
    'terreno.cimeAccesi': 'Accesi: cerco le vette entro {km} km…',
    'terreno.cimeCerco': 'Sto cercando le montagne qui attorno…',
    'terreno.cimeAspettoTerreno': 'Ho {n} vette qui attorno: aspetto la forma del terreno per sapere quali si vedono.',
    'terreno.cimeDietroCresta': 'Le {n} vette entro {km} km restano tutte dietro alla prima cresta: da qui non se ne vede nessuna.',
    'terreno.cimeNessuna': 'Nessuna vetta con un nome entro {km} km: nelle Impostazioni puoi allargare la ricerca.',
    'terreno.cimeViste': 'Sopra l\'orizzonte si riconoscono {n} vette entro {raggio} km: la più imponente è {nome} ({quota} m), a {km} km verso {dove}, alta {alt}°.',
    'terreno.acqueSpente': 'Laghi e fiumi spenti.',
    'terreno.acqueCerco': 'Sto cercando laghi e fiumi qui attorno…',
    'terreno.acqueFallito': 'Laghi e fiumi: {motivo}. L\'orizzonte resta quello di prima.',
