    'aurora.soloRosso': '{quale}: da qui il verde resta sotto l\'orizzonte — è oltre la curvatura della Terra — e si affaccia solo la parte alta delle tende, il rosso dell\'ossigeno a duecento chilometri: fino a {alt}° sopra l\'orizzonte, verso {direzione}. È l\'aurora che si è vista dall\'Italia nel maggio 2024.',
