    // --- Missione Cielo · i tre gradini, la scoperta e i ripieghi -----
    // Gli enigmi, i segni e gli aneddoti hanno tre gradini di ripiego, e
    // sono sempre gli stessi tre: il nome proprio del bersaglio, la sua
    // specie di catalogo, la sua famiglia. Le voci qui sotto sono i due
    // gradini di sotto — quelli che fanno sì che anche la centoquarantesima
    // galassia senza nome abbia qualcosa di vero da dire.
    'missione.esperienzaNota.bambini': 'Solo cose che non si possono sbagliare, indovinelli semplici e la direzione già detta.',
    'missione.esperienzaNota.curiosi': 'L’indovinello e il segno da cercare. Capire dove guardare tocca a te.',
    'missione.esperienzaNota.sfida': 'Solo l’indovinello, cielo profondo compreso. Ogni aiuto va chiesto.',
    'missione.sbirciaBersagli': 'Sbircia i bersagli',
    'missione.nascondiBersagli': 'Nascondi di nuovo i bersagli',
