    'missione.curiosita.centroGalattico.2': 'Lì dentro c’è Sagittarius A*, un buco nero di quattro milioni di masse solari. Lo sappiamo perché per trent’anni si sono seguite le orbite delle stelle che gli girano attorno: una di loro fa un giro completo in sedici anni, a un ventesimo della velocità della luce.',

