    'ui.gli-orari-da-casa-tua': 'Gli orari, da casa tua',
    'ui.gps-del-dispositivo': 'GPS del dispositivo',
    'ui.gradi-decimali-con-il-punto-sud-e-ovest-si': 'Gradi decimali, con il punto: sud e ovest si scrivono col meno (−). Su una mappa online basta tenere premuto sul punto per leggerle.',
    'ui.guarda': 'Guarda',
    'ui.guarda-il-cielo-da-qui': 'Guarda il cielo da qui',
    'ui.guarda-verso': 'Guarda verso',
    'ui.guarda-verso-est': 'Guarda verso est',
    'ui.guarda-verso-nord': 'Guarda verso nord',
    'ui.guarda-verso-ovest': 'Guarda verso ovest',
    'ui.guarda-verso-sud': 'Guarda verso sud',
    'ui.guardalo-da-sotto': 'Guardalo da sotto',
    'ui.ho-visto': 'Ho visto!',
    'ui.i-laghi-e-i-fiumi-veri-attorno-a-te': 'I laghi e i fiumi veri attorno a te, disegnati dove sono e alla distanza a cui sono: l\'acqua ferma riflette il cielo come uno specchio, e la Luna ci fa la sua strada di luce. Si vedono solo quelli che non restano dietro a una cresta. Si scaricano da OpenStreetMap una volta sola e poi restano anche senza rete; fin dove cercarli si decide nelle Impostazioni',
    'ui.i-nomi-delle-montagne-che-spuntano-sopra-l': 'I nomi delle montagne che spuntano sopra l\'orizzonte, con la loro quota, agganciati alla vetta vera da un filo: si nominano solo quelle che da qui si vedono davvero, non quelle nascoste dietro a una cresta più vicina. Nascono spenti; una volta accesi si scaricano una volta sola e la scelta si ricorda. Fin dove cercarle si decide nelle Impostazioni',
    'ui.i-quadri-della-lezione': 'I quadri della lezione',
    'ui.ics-aiuto': 'Scarica un file <code>.ics</code> con i prossimi eventi: il calendario del telefono penserà lui ai promemoria, anche ad app chiusa.',
    'ui.il-cerchio-che-il-sole-percorre-in-un-anno': 'Il cerchio che il Sole percorre in un anno fra le stelle: il piano dell\'orbita terrestre visto di taglio. I pianeti stanno sempre a pochi gradi da questa linea, e il filo a piombo misura quanti. Resta accesa qualunque oggetto si scelga, finché non la si spegne',
    'ui.il-cielo-a-tutto-schermo-con-i-comandi-in': 'Il cielo a tutto schermo, con i comandi in sovrimpressione',
    'ui.il-cielo-che-hai': 'Il cielo che hai',
    'ui.il-cielo-da-cui-osservi': 'Il cielo da cui osservi',
    'ui.il-cielo-di-stanotte-da-casa-tua': 'Il cielo di stanotte, da casa tua',
    'ui.il-cielo-mostrato-non-e-quello-di-adesso': 'Il cielo mostrato non è quello di adesso: tocca per tornare al tempo reale',
    'ui.il-cielo-occupa-tutto-lo-schermo-anche-con': 'Il cielo occupa tutto lo schermo (anche con un doppio clic sulla mappa)',
    'ui.il-nord-punta-storto-bussola-e-posizione': 'Il Nord punta storto? Bussola e posizione',
    'ui.il-palazzo-di-fronte-la-collina-gli-alberi': 'Il palazzo di fronte, la collina, gli alberi. Dichiara quanto sono alti in gradi (un pugno a braccio teso è circa 10°) e da lì in poi l\'app smette di proporti cose che da casa tua non vedrai mai. Zero vuol dire orizzonte libero.',
    'ui.il-percorso-del-cono-d-ombra-sulla-terra': 'Il percorso del cono d\'ombra sulla Terra',
    'ui.il-planetario-e-su-questo-istante': 'Il planetario è su questo istante.',
    'ui.il-planetario-punta-il-telefono-verso-il': 'Il planetario: punta il telefono verso il cielo e vedi cosa c\'è',
    'ui.il-punto-che-al-massimo-ha-la-luna': 'Il punto che al massimo ha la Luna esattamente sopra la testa: da lì si guarda in alto, senza ostacoli.',
    'ui.il-resto-dell-app-dice-cosa-c-e-stanotte-qui': 'Il resto dell\'app dice cosa c\'è stanotte. Qui c\'è come inquadrarlo:\n          i conti sono fatti sul tuo strumento, le istruzioni parlano di manopole vere, e le due fasi difficili —\n          mettere l\'asse a Nord e trovare l\'oggetto — le fai guidato, con livella, bussola e push-to del telefono.',
    'ui.il-sistema-solare-a-tutto-schermo-con-la': 'Il Sistema Solare a tutto schermo, con la barra del tempo in sovrimpressione',
    'ui.il-sistema-solare-adesso': 'Il Sistema Solare, adesso',
    'ui.il-sistema-solare-in-3d': 'Il Sistema Solare in 3D',
    'ui.il-sistema-solare-visto-da-fuori-nello': 'Il Sistema Solare visto da fuori, nello stesso istante: si apre a tutto schermo, puntato sulla Terra',
