    'ui.istante-mostrato-apri-i-comandi-del-tempo': 'Istante mostrato: apri i comandi del tempo',
    'ui.kp-vero': 'Kp vero',
    'ui.l-aria-sopra-di-te-colore-del-cielo-nuvole': 'L\'aria sopra di te: colore del cielo, nuvole, aurora',
    'ui.l-ho-vista-scrivilo-nel-diario': 'L\'ho vista: scrivilo nel diario',
    'ui.l-istante-mostrato-tocca-per-data-e-passo': 'L\'istante mostrato: tocca per data e passo del tempo',
    'ui.l-istante-mostrato-tocca-per-scrivere-una': 'L\'istante mostrato: tocca per scrivere una data',
    'ui.l-orizzonte-attorno-a-te': 'L\'orizzonte attorno a te',
    'ui.l-orizzonte-prende-la-forma-vera-del-terreno': 'L\'orizzonte prende la forma vera del terreno attorno a te: colline, montagne, mare, pianura — ognuno col suo colore. Si scarica una volta sola e poi resta anche senza rete. Spento, il terreno non viene disegnato. Ingrandendo molto su un astro il terreno diventa trasparente da sé, come in Stellarium',
    'ui.la-cartella-di-astrocalendario-non-e-ancora': 'La cartella di AstroCalendario non è ancora collegata',
    'ui.la-citta-in-elenco-o-le-coordinate-esatte': 'La città in elenco o le coordinate esatte. Funziona anche offline e senza permessi.',
    'ui.la-classifica-usa-le-strade-e-i-divieti-di': 'La classifica usa le strade e i divieti di accesso presenti in OpenStreetMap, oltre a quota e profilo del terreno. I dati possono essere incompleti: prima di partire verifica segnaletica, possibilità di fermarti, meteo e sicurezza del luogo.',
    'ui.la-forma-vera-del-terreno-non-solo-la-sua': 'La forma vera del terreno, non solo la sua sagoma: le valli che scendono, i fianchi delle colline, il solco del fiume, disegnati a tratti come su una tavola panoramica. Attorno a te il passo è di ventisette metri, contro i tre gradi del profilo a bande. Si scarica una volta sola per luogo (da quattro a sei tessere) e poi resta anche senza rete. Spento, torna il profilo a bande',
    'ui.la-luna-entra-nell-ombra-della-terra-chi-la': 'La Luna entra nell\'ombra della Terra: chi la vede in cielo la vede tutta, nello stesso istante',
    'ui.la-mappa-a-tutto-schermo-con-i-comandi-in': 'La mappa a tutto schermo, con i comandi in sovrimpressione',
    'ui.la-mappa-non-e-disponibile-adesso-serve-la': 'La mappa non è disponibile adesso — serve la rete per caricarla.\n              Le coordinate del pannello «Da Google Maps» funzionano lo stesso.',
    'ui.la-modalita-hover-e-disponibile-quando-la': 'La modalità hover è disponibile quando la vista segue il telefono',
    'ui.la-posizione-resta-salvata-solo-su-questo': 'La posizione resta salvata solo su questo dispositivo: non viene inviata a nessuno, e l\'app la usa per fare i conti in locale.',
    'ui.la-scegli-tu': 'La scegli tu',
    'ui.la-strada-che-l-oggetto-scelto-percorre-nel': 'La strada che l\'oggetto scelto percorre nel cielo nelle ore attorno a questo istante: tratteggiata dove è già passato, piena dove sta andando, con l\'ora segnata di ora in ora',
    'ui.la-terra-e-la-luna-da-vicino-coi-due-coni-d': 'La Terra e la Luna da vicino, coi due coni d\'ombra: è qui che si vede perché un\'eclissi non capita a ogni Luna piena — l\'orbita della Luna è inclinata di 5,1°, e a quella distanza sono trentaquattromila chilometri fuori bersaglio.',
    'ui.la-terra-sotto-di-te-terreno-rilievo-luci': 'La terra sotto di te: terreno, rilievo, luci, acque',
    'ui.la-tua-nota': 'La tua nota',
    'ui.la-tua-posizione': 'La tua posizione',
    'ui.laboratorio': 'Laboratorio',
    'ui.laboratorio-didattico-e-simulazioni': 'Laboratorio didattico e simulazioni interattive della meccanica celeste',
    'ui.laghi-e-fiumi': 'Laghi e fiumi',
    'ui.lascia-solo-gli-astri-che-adesso-stanno': 'Lascia solo gli astri che adesso stanno sopra l\'orizzonte',
    'ui.latitudine': 'Latitudine',
    'ui.le-cupole-di-luce-dei-paesi-veri-attorno-a': 'Le cupole di luce dei paesi veri attorno a te, col loro nome sull\'orizzonte: dicono da che parte NON cercare le cose deboli. Di giorno non si vedono',
    'ui.le-distanze-fra-le-orbite-sono-compresse-per': 'Le distanze fra le orbite sono compresse per farcele stare tutte nello\n          schermo: Saturno è davvero venticinque volte più lontano di Mercurio. Gli angoli, che sono\n          quello di cui parla la lezione, sono invece quelli veri.',
    'ui.le-eclissi-di-casa-tua': 'Le eclissi di casa tua',
    'ui.le-figure-delle-costellazioni': 'Le figure delle costellazioni',
    'ui.le-ottantotto-costellazioni-la-figura-il': 'Le ottantotto costellazioni: la figura, il disegno, i nomi che le hanno dato le altre culture, e da qui si vede o no. Metà sono australi e dall\'Italia non sorgono mai: da lì si può andare.',
    'ui.le-registrazioni-salvate-con-astrocalendario': 'Le registrazioni salvate con AstroCalendario, disponibili anche senza rete',
    'ui.le-stelle-luminose-di-riferimento': 'Le stelle luminose di riferimento',
    'ui.le-tue-osservazioni': 'Le tue osservazioni',
    'ui.le-tue-osservazioni-e-i-traguardi-raggiunti': 'Le tue osservazioni e i traguardi raggiunti',
    'ui.lenta': 'lenta',
    'ui.linea-del-giorno-e-della-notte': 'Linea del giorno e della notte',
    'ui.lo-zoom-con-due-dita-rotellina-o-trackpad': 'Lo zoom con due dita, rotellina o trackpad resta sempre disponibile.',
    'ui.longitudine': 'Longitudine',
    'ui.luci-delle-citta': 'Luci delle città',
    'ui.luna-allo-zenit': 'Luna allo zenit',
    'ui.luogo-incolla-aiuto': 'In Google Maps tieni premuto sul punto: compaiono le coordinate, e si copiano con un tocco. Vanno bene anche i link lunghi con <code>@</code>, i gradi e primi (45°58\'34"N 7°39\'29"E) e i due numeri secchi. I link corti <code>maps.app.goo.gl</code> no: aprili una volta, e copia quello che diventano.',
    'ui.mandalo-con-le-app-del-telefono': 'Mandalo con le app del telefono',
    'ui.mappa': 'Mappa',
    'ui.mappa-a-tutto-schermo': 'Mappa a tutto schermo',
