    'ui.mappa-sul-computer-fai-doppio-clic-sul': 'Mappa: sul computer fai doppio clic; sul telefono tocca un punto, poi scegli Vai qua',
    'ui.massimo': 'Massimo',
    'ui.mese': 'Mese',
    'ui.mese-corrente': 'Mese corrente',
    'ui.mini-mappa-di-vai-qua': 'Mini-mappa di “Vai qua”',
