    'ui.ogni-riga-e-un-eclissi-solare-che-da-questo': 'Ogni riga e\' un\'eclissi solare che da questo punto si vede,\n          almeno in parte. Toccane una per aprirne la mappa.',
    'ui.oppure-un-intervallo': 'Oppure un intervallo',
    'ui.orari-calcolati-per-il-punto-che-hai-scelto': 'Orari calcolati per il punto che hai scelto.\n            Tocca una riga per portare lì il cursore del tempo.',
